import numpy as np


class ConstraintBasedLearner:
    """Learn model parameters subject to logical constraints."""

    def __init__(self, n_params, constraints):
        self.n_params = n_params
        self.constraints = constraints  # list of {'type': str, 'params': dict}
        self.params = np.random.randn(n_params) * 0.1

    def _sigmoid(self, x):
        return np.where(x >= 0, 1 / (1 + np.exp(-x)), np.exp(x) / (1 + np.exp(x)))

    def evaluate_constraint(self, constraint, params=None):
        """Evaluate how well a constraint is satisfied (1.0 = fully satisfied)."""
        p = params if params is not None else self.params
        ctype = constraint['type']

        if ctype == 'monotonic':
            # params[i] should be >= 0 for all i in indices
            indices = constraint['params']['indices']
            violations = np.sum(np.maximum(0, -p[indices]))
            return 1.0 / (1.0 + violations)

        elif ctype == 'sum_equals':
            # sum(params[indices]) should equal target
            indices = constraint['params']['indices']
            target = constraint['params']['target']
            diff = abs(np.sum(p[indices]) - target)
            return 1.0 / (1.0 + diff)

        elif ctype == 'ordering':
            # params[i] >= params[j] for pairs (i, j)
            pairs = constraint['params']['pairs']
            violations = 0.0
            for i, j in pairs:
                violations += np.maximum(0, p[j] - p[i])
            return 1.0 / (1.0 + violations)

        elif ctype == 'sparsity':
            # Encourage params to be near zero
            l1_norm = np.sum(np.abs(p))
            target = constraint['params'].get('target_l1', 1.0)
            return 1.0 / (1.0 + abs(l1_norm - target))

        return 0.0

    def constraint_loss(self, params=None):
        """Compute total constraint violation loss."""
        total_loss = 0.0
        for constraint in self.constraints:
            satisfaction = self.evaluate_constraint(constraint, params)
            total_loss += (1.0 - satisfaction)
        return total_loss

    def project(self, params):
        """Project parameters onto constraint-satisfying region."""
        projected = params.copy()

        for constraint in self.constraints:
            if constraint['type'] == 'monotonic':
                indices = constraint['params']['indices']
                projected[indices] = np.maximum(0, projected[indices])

            elif constraint['type'] == 'sum_equals':
                indices = constraint['params']['indices']
                target = constraint['params']['target']
                current_sum = np.sum(projected[indices])
                if abs(current_sum) > 1e-10:
                    projected[indices] *= target / current_sum

            elif constraint['type'] == 'ordering':
                pairs = constraint['params']['pairs']
                for i, j in pairs:
                    if projected[j] > projected[i]:
                        avg = (projected[i] + projected[j]) / 2
                        projected[i] = projected[j] = avg

        return projected

    def train(self, X, y, n_epochs=200, lr=0.01, constraint_weight=0.5):
        """Train with data loss and constraint penalties."""
        n_samples = X.shape[0]

        for epoch in range(n_epochs):
            # TODO: Forward pass (linear model)
            predictions = X @ self.params

            # TODO: Data loss (MSE)
            data_loss = np.mean((predictions - y) ** 2)

            # TODO: Constraint loss
            c_loss = self.constraint_loss()

            # TODO: Combined gradient
            data_grad = 2.0 * X.T @ (predictions - y) / n_samples

            # Numerical gradient for constraint loss
            epsilon = 1e-5
            constraint_grad = np.zeros_like(self.params)
            for i in range(self.n_params):
                perturbed = self.params.copy()
                perturbed[i] += epsilon
                constraint_grad[i] = (self.constraint_loss(perturbed) - c_loss) / epsilon

            # TODO: Update parameters
            total_grad = data_grad + constraint_weight * constraint_grad
            self.params -= lr * total_grad

            # TODO: Project onto constraints every few epochs
            if epoch % 10 == 0:
                self.params = self.project(self.params)

        return self.params


if __name__ == "__main__":
    np.random.seed(42)
    X = np.random.rand(100, 4)
    y = 2.0 * X[:, 0] + 1.0 * X[:, 1] - 0.5 * X[:, 2] + 0.3 * X[:, 3]

    constraints = [
        {'type': 'monotonic', 'params': {'indices': [0, 1]}},
        {'type': 'ordering', 'params': {'pairs': [(0, 2), (1, 3)]}},
    ]

    learner = ConstraintBasedLearner(n_params=4, constraints=constraints)
    params = learner.train(X, y, n_epochs=200, lr=0.01)
    print(f"Learned params: {params}")
    print(f"Constraint satisfaction: {1 - learner.constraint_loss():.4f}")
